// ---------------------------------------------------------------------------
// Waterfall Clock — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Minute_Main_y7ai = [
  A('wf/digits/d_0.png'),
  A('wf/digits/d_1.png'),
  A('wf/digits/d_2.png'),
  A('wf/digits/d_3.png'),
  A('wf/digits/d_4.png'),
  A('wf/digits/d_5.png'),
  A('wf/digits/d_6.png'),
  A('wf/digits/d_7.png'),
  A('wf/digits/d_8.png'),
  A('wf/digits/d_9.png'),
]

const img_Weekday_y27u = [
  A('wf/ui/day_0.png'),
  A('wf/ui/day_1.png'),
  A('wf/ui/day_2.png'),
  A('wf/ui/day_3.png'),
  A('wf/ui/day_4.png'),
  A('wf/ui/day_5.png'),
  A('wf/ui/day_6.png'),
]

const img_Day_y4k7 = [
  A('wf/ui/num_0.png'),
  A('wf/ui/num_1.png'),
  A('wf/ui/num_2.png'),
  A('wf/ui/num_3.png'),
  A('wf/ui/num_4.png'),
  A('wf/ui/num_5.png'),
  A('wf/ui/num_6.png'),
  A('wf/ui/num_7.png'),
  A('wf/ui/num_8.png'),
  A('wf/ui/num_9.png'),
]

const img_Month_y7c7 = [
  A('wf/ui/month_0.png'),
  A('wf/ui/month_1.png'),
  A('wf/ui/month_2.png'),
  A('wf/ui/month_3.png'),
  A('wf/ui/month_4.png'),
  A('wf/ui/month_5.png'),
  A('wf/ui/month_6.png'),
  A('wf/ui/month_7.png'),
  A('wf/ui/month_8.png'),
  A('wf/ui/month_9.png'),
  A('wf/ui/month_10.png'),
  A('wf/ui/month_11.png'),
]

const img_Minute_AOD_y6v6 = [
  A('wf/digits/a_0.png'),
  A('wf/digits/a_1.png'),
  A('wf/digits/a_2.png'),
  A('wf/digits/a_3.png'),
  A('wf/digits/a_4.png'),
  A('wf/digits/a_5.png'),
  A('wf/digits/a_6.png'),
  A('wf/digits/a_7.png'),
  A('wf/digits/a_8.png'),
  A('wf/digits/a_9.png'),
]

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(0),
      y: px(0),
      anim_path: 'images/anim',
      anim_prefix: 'bg',
      anim_ext: 'png',
      anim_fps: 8,
      anim_size: 25,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(57),
      minute_startY: px(219),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_y7ai,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(57),
      hour_startY: px(59),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_Main_y7ai,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Butterfly 1 (IMG)
    const variants_0 = [A('wf/bf/b0_00.png'), A('wf/bf/b0_01.png'), A('wf/bf/b0_02.png'), A('wf/bf/b0_10.png'), A('wf/bf/b0_11.png'), A('wf/bf/b0_12.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(120),
      w: px(44),
      h: px(44),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.bf0 = variant_0
    F.bf0 = variants_0

    // Butterfly 2 (IMG)
    const variants_1 = [A('wf/bf/b3_00.png'), A('wf/bf/b3_01.png'), A('wf/bf/b3_02.png'), A('wf/bf/b3_10.png'), A('wf/bf/b3_11.png'), A('wf/bf/b3_12.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(240),
      y: px(300),
      w: px(44),
      h: px(44),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.bf1 = variant_1
    F.bf1 = variants_1

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(83),
      y: px(413),
      week_en: img_Weekday_y27u,
      week_sc: img_Weekday_y27u,
      week_tc: img_Weekday_y27u,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Dot (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(116),
      y: px(414),
      w: px(5),
      h: px(5),
      src: A('wf/ui/dot.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(125),
      day_startY: px(413),
      day_zero: 1,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_y4k7,
      day_sc_array: img_Day_y4k7,
      day_tc_array: img_Day_y4k7,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Month (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      month_startX: px(147),
      month_startY: px(413),
      month_zero: 0,
      month_space: px(0),
      month_align: ui.align.LEFT,
      month_follow: 0,
      month_is_character: true,
      month_en_array: img_Month_y7c7,
      month_sc_array: img_Month_y7c7,
      month_tc_array: img_Month_y7c7,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(193),
      y: px(413),
      w: px(27),
      type: ui.data_type.HEART,
      font_array: img_Day_y4k7,
      align_h: ui.align.RIGHT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // BPM label (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(224),
      y: px(415),
      w: px(20),
      h: px(20),
      src: A('wf/ui/bpm.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(262),
      y: px(413),
      w: px(45),
      type: ui.data_type.STEP,
      font_array: img_Day_y4k7,
      align_h: ui.align.LEFT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(113),
      minute_startY: px(232),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_AOD_y6v6,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(113),
      hour_startY: px(132),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Minute_AOD_y6v6,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // The background is a native frame animation. The only code: two butterflies wander at random in front of the clock.
      const TICK = 100, FLAP = [0, 1, 2, 1], HALF = 22;
      const rnd = (a, b) => a + Math.random() * (b - a);
      const BUGS = ['bf0', 'bf1'].map((h, i) => ({ h, x: rnd(40, 340), y: rnd(40, 380), vx: 0, vy: 0, tx: rnd(20, 370), ty: rnd(30, 400), n: Math.floor(rnd(10, 40)), sp: 2.4 + i * 0.6 }));
      let tk = 0, id = null;
      const tick = () => {
        id = null;
        tk++;
        try {
          const fl = FLAP[tk % 4];
          for (const b of BUGS) {
            if (--b.n <= 0) { b.tx = rnd(20, 370); b.ty = rnd(30, 400); b.n = Math.floor(rnd(15, 55)); }
            const dx = b.tx - b.x, dy = b.ty - b.y, d = Math.hypot(dx, dy) || 1;
            b.vx = b.vx * 0.8 + (dx / d) * b.sp * 0.5 + rnd(-0.7, 0.7);
            b.vy = b.vy * 0.8 + (dy / d) * b.sp * 0.5 + rnd(-0.7, 0.7);
            b.x += b.vx; b.y += b.vy;
            W[b.h].setProperty(ui.prop.MORE, { x: pxv(Math.round(b.x - HALF)), y: pxv(Math.round(b.y - HALF)), src: F[b.h][(b.vx < 0 ? 3 : 0) + fl] });
          }
        } catch (e) {}
        id = setTimeout(tick, TICK);
      };
      const start = () => { if (id === null) tick(); };
      const stop = () => { if (id !== null) { clearTimeout(id); id = null; } };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();
    }
  },

  build() {
    this.initView()
  },
})
